## 1. Dijkstra算法

```javascript
class Dijkstra {
    static findPath(grid, start, end, visualCallback = null) {
        const rows = grid.length;
        const cols = grid[0].length;
        const distances = Array(rows).fill().map(() => Array(cols).fill(Infinity));
        const previous = Array(rows).fill().map(() => Array(cols).fill(null));
        const visited = Array(rows).fill().map(() => Array(cols).fill(false));

        // 优先队列（最小堆）
        const pq = new PriorityQueue((a, b) => a.dist < b.dist);

        distances[start.row][start.col] = 0;
        pq.enqueue({row: start.row, col: start.col, dist: 0});

        const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        while (!pq.isEmpty()) {
            const current = pq.dequeue();
            const {row, col} = current;

            if (visited[row][col]) continue;
            visited[row][col] = true;

            // 可视化回调
            if (visualCallback && !(row === start.row && col === start.col)) {
                visualCallback(row, col, 'visited');
            }

            // 到达终点
            if (row === end.row && col === end.col) {
                return this.reconstructPath(previous, start, end);
            }

            // 检查邻居
            for (let [dr, dc] of directions) {
                const newRow = row + dr;
                const newCol = col + dc;

                if (this.isValid(newRow, newCol, rows, cols) && 
                    !visited[newRow][newCol] && 
                    grid[newRow][newCol] !== 1) { // 1表示障碍物

                    const newDist = distances[row][col] + 1;

                    if (newDist < distances[newRow][newCol]) {
                        distances[newRow][newCol] = newDist;
                        previous[newRow][newCol] = {row, col};
                        pq.enqueue({row: newRow, col: newCol, dist: newDist});

                        if (visualCallback) {
                            visualCallback(newRow, newCol, 'frontier');
                        }
                    }
                }
            }
        }

        return null; // 无路径
    }

    static isValid(row, col, rows, cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    static reconstructPath(previous, start, end) {
        const path = [];
        let current = end;

        while (current) {
            path.unshift(current);
            current = previous[current.row][current.col];
        }

        return path.length > 1 ? path : null;
    }
}
```

## 2. A*算法

```javascript
class AStar {
    static findPath(grid, start, end, visualCallback = null) {
        const rows = grid.length;
        const cols = grid[0].length;
        const gScore = Array(rows).fill().map(() => Array(cols).fill(Infinity));
        const fScore = Array(rows).fill().map(() => Array(cols).fill(Infinity));
        const previous = Array(rows).fill().map(() => Array(cols).fill(null));
        const visited = Array(rows).fill().map(() => Array(cols).fill(false));

        // 优先队列按f值排序
        const openSet = new PriorityQueue((a, b) => a.f < b.f);

        gScore[start.row][start.col] = 0;
        fScore[start.row][start.col] = this.heuristic(start, end);

        openSet.enqueue({
            row: start.row, 
            col: start.col, 
            f: fScore[start.row][start.col]
        });

        const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        while (!openSet.isEmpty()) {
            const current = openSet.dequeue();
            const {row, col} = current;

            if (visited[row][col]) continue;
            visited[row][col] = true;

            // 可视化回调
            if (visualCallback && !(row === start.row && col === start.col)) {
                visualCallback(row, col, 'visited');
            }

            // 到达终点
            if (row === end.row && col === end.col) {
                return this.reconstructPath(previous, start, end);
            }

            // 检查邻居
            for (let [dr, dc] of directions) {
                const newRow = row + dr;
                const newCol = col + dc;

                if (this.isValid(newRow, newCol, rows, cols) && 
                    !visited[newRow][newCol] && 
                    grid[newRow][newCol] !== 1) {

                    const tentativeG = gScore[row][col] + 1;

                    if (tentativeG < gScore[newRow][newCol]) {
                        previous[newRow][newCol] = {row, col};
                        gScore[newRow][newCol] = tentativeG;
                        fScore[newRow][newCol] = tentativeG + this.heuristic({row: newRow, col: newCol}, end);

                        openSet.enqueue({
                            row: newRow, 
                            col: newCol, 
                            f: fScore[newRow][newCol]
                        });

                        if (visualCallback) {
                            visualCallback(newRow, newCol, 'frontier');
                        }
                    }
                }
            }
        }

        return null;
    }

    // 曼哈顿距离启发式函数
    static heuristic(a, b) {
        return Math.abs(a.row - b.row) + Math.abs(a.col - b.col);
    }

    // 也可以使用欧几里得距离
    static euclideanHeuristic(a, b) {
        return Math.sqrt(Math.pow(a.row - b.row, 2) + Math.pow(a.col - b.col, 2));
    }

    static isValid(row, col, rows, cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    static reconstructPath(previous, start, end) {
        const path = [];
        let current = end;

        while (current) {
            path.unshift(current);
            current = previous[current.row][current.col];
        }

        return path.length > 1 ? path : null;
    }
}
```

## 3. BFS算法

```javascript
class BFS {
    static findPath(grid, start, end, visualCallback = null) {
        const rows = grid.length;
        const cols = grid[0].length;
        const visited = Array(rows).fill().map(() => Array(cols).fill(false));
        const previous = Array(rows).fill().map(() => Array(cols).fill(null));
        const queue = [];

        queue.push(start);
        visited[start.row][start.col] = true;

        const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        while (queue.length > 0) {
            const current = queue.shift();
            const {row, col} = current;

            // 可视化回调
            if (visualCallback && !(row === start.row && col === start.col)) {
                visualCallback(row, col, 'visited');
            }

            // 到达终点
            if (row === end.row && col === end.col) {
                return this.reconstructPath(previous, start, end);
            }

            // 检查邻居
            for (let [dr, dc] of directions) {
                const newRow = row + dr;
                const newCol = col + dc;

                if (this.isValid(newRow, newCol, rows, cols) && 
                    !visited[newRow][newCol] && 
                    grid[newRow][newCol] !== 1) {

                    visited[newRow][newCol] = true;
                    previous[newRow][newCol] = {row, col};
                    queue.push({row: newRow, col: newCol});

                    if (visualCallback) {
                        visualCallback(newRow, newCol, 'frontier');
                    }
                }
            }
        }

        return null;
    }

    static isValid(row, col, rows, cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    static reconstructPath(previous, start, end) {
        const path = [];
        let current = end;

        while (current) {
            path.unshift(current);
            current = previous[current.row][current.col];
        }

        return path.length > 1 ? path : null;
    }
}
```

## 4. 优先队列辅助类

```javascript
class PriorityQueue {
    constructor(compare) {
        this.heap = [];
        this.compare = compare;
    }

    enqueue(item) {
        this.heap.push(item);
        this.heapifyUp(this.heap.length - 1);
    }

    dequeue() {
        if (this.isEmpty()) return null;

        const min = this.heap[0];
        const end = this.heap.pop();

        if (this.heap.length > 0) {
            this.heap[0] = end;
            this.heapifyDown(0);
        }

        return min;
    }

    isEmpty() {
        return this.heap.length === 0;
    }

    heapifyUp(index) {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (!this.compare(this.heap[index], this.heap[parentIndex])) break;

            [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
            index = parentIndex;
        }
    }

    heapifyDown(index) {
        while (true) {
            let minIndex = index;
            const leftChild = 2 * index + 1;
            const rightChild = 2 * index + 2;

            if (leftChild < this.heap.length && this.compare(this.heap[leftChild], this.heap[minIndex])) {
                minIndex = leftChild;
            }

            if (rightChild < this.heap.length && this.compare(this.heap[rightChild], this.heap[minIndex])) {
                minIndex = rightChild;
            }

            if (minIndex !== index) {
                [this.heap[index], this.heap[minIndex]] = [this.heap[minIndex], this.heap[index]];
                index = minIndex;
            } else {
                break;
            }
        }
    }
}
