    <script>
        class PathfindingVisualizer {
            constructor() {
                this.canvas = document.getElementById('grid-canvas');
                this.ctx = this.canvas.getContext('2d');
                this.cellSize = 20;
                this.rows = Math.floor(this.canvas.height / this.cellSize);
                this.cols = Math.floor(this.canvas.width / this.cellSize);

                this.grid = Array(this.rows).fill().map(() => Array(this.cols).fill(0));
                this.start = null;
                this.end = null;
                this.isRunning = false;
                this.visitedCount = 0;

                this.initializeEventListeners();
                this.drawGrid();
            }

            initializeEventListeners() {
                // Canvas 点击事件
                this.canvas.addEventListener('click', (e) => this.handleCanvasClick(e));
                this.canvas.addEventListener('mousemove', (e) => this.handleCanvasMouseMove(e));
                this.canvas.addEventListener('mousedown', (e) => this.isMouseDown = true);
                this.canvas.addEventListener('mouseup', (e) => this.isMouseDown = false);

                // 控制按钮事件
                document.getElementById('start-btn').addEventListener('click', () => this.startPathfinding());
                document.getElementById('clear-path').addEventListener('click', () => this.clearPath());
                document.getElementById('clear-all').addEventListener('click', () => this.clearAll());

                // 速度滑块
                document.getElementById('speed').addEventListener('input', (e) => {
                    document.getElementById('speed-value').textContent = e.target.value;
                });
            }

            handleCanvasClick(e) {
                if (this.isRunning) return;

                const rect = this.canvas.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                const col = Math.floor(x / this.cellSize);
                const row = Math.floor(y / this.cellSize);

                if (row >= 0 && row < this.rows && col >= 0 && col < this.cols) {
                    this.handleCellClick(row, col);
                }
            }

            handleCanvasMouseMove(e) {
                if (!this.isMouseDown || this.isRunning) return;

                const rect = this.canvas.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                const col = Math.floor(x / this.cellSize);
                const row = Math.floor(y / this.cellSize);

                if (row >= 0 && row < this.rows && col >= 0 && col < this.cols) {
                    const mode = document.getElementById('mode').value;
                    if (mode === 'wall' || mode === 'erase') {
                        this.handleCellClick(row, col);
                    }
                }
            }

            handleCellClick(row, col) {
                const mode = document.getElementById('mode').value;

                switch (mode) {
                    case 'start':
                        if (this.start) {
                            this.grid[this.start.row][this.start.col] = 0;
                        }
                        this.start = {row, col};
                        this.grid[row][col] = 2;
                        break;
                    case 'end':
                        if (this.end) {
                            this.grid[this.end.row][this.end.col] = 0;
                        }
                        this.end = {row, col};
                        this.grid[row][col] = 3;
                        break;
                    case 'wall':
                        if (this.grid[row][col] === 0) {
                            this.grid[row][col] = 1;
                        }
                        break;
                    case 'erase':
                        if (this.grid[row][col] === 1) {
                            this.grid[row][col] = 0;
                        }
                        break;
                }

                this.drawGrid();
            }

            drawGrid() {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                for (let row = 0; row < this.rows; row++) {
                    for (let col = 0; col < this.cols; col++) {
                        this.drawCell(row, col, this.grid[row][col]);
                    }
                }

                // 绘制网格线
                this.ctx.strokeStyle = '#ddd';
                this.ctx.lineWidth = 1;

                for (let row = 0; row <= this.rows; row++) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(0, row * this.cellSize);
                    this.ctx.lineTo(this.canvas.width, row * this.cellSize);
                    this.ctx.stroke();
                }

                for (let col = 0; col <= this.cols; col++) {
                    this.ctx.beginPath();
                    this.ctx.moveTo(col * this.cellSize, 0);
                    this.ctx.lineTo(col * this.cellSize, this.canvas.height);
                    this.ctx.stroke();
                }
            }

            drawCell(row, col, type, isPath = false) {
                const x = col * this.cellSize;
                const y = row * this.cellSize;

                let color;
                switch (type) {
                    case 0: color = 'white'; break;
                    case 1: color = '#333'; break;
                    case 2: color = '#28a745'; break; // 起点
                    case 3: color = '#dc3545'; break; // 终点
                    case 'visited': color = '#87ceeb'; break;
                    case 'frontier': color = '#ffeb3b'; break;
                    case 'path': color = '#ff4081'; break;
                    default: color = 'white';
                }

                if (isPath) color = '#ff4081';

                this.ctx.fillStyle = color;
                this.ctx.fillRect(x, y, this.cellSize, this.cellSize);

                if (type === 1 || type === 2 || type === 3) {
                    this.ctx.strokeStyle = '#333';
                    this.ctx.lineWidth = 2;
                    this.ctx.strokeRect(x, y, this.cellSize, this.cellSize);
                }
            }

